// KScreenClient (app/kde/kscreen_client.cpp) when KScreen's launcher leaves the bus and D-Bus
// activation starts it again. Goals S15.14, S15.27, S15.29 and S15.30 in GOALS.md.
//
// The bus (activating_session.conf, generated by app/tests/CMakeLists.txt) can start exactly the
// stand-ins this binary serves as, all under io.wallpaperx.test.Launcher., and nothing else;
// refuseUnlessPrivateBus proves it. A stand-in is this binary started by the bus with --stand-in:
// it answers like KScreen's launcher and logs each start and call to a file, so starts are counted,
// not inferred from calls.

#include "fake_kscreen.h"
#include "kscreen_client.h"
#include "kscreen_fixtures.h"
#include "tests/test_report.h"

#include <QCoreApplication>
#include <QDBusMetaType>
#include <QDBusPendingCallWatcher>
#include <QDBusVirtualObject>
#include <QElapsedTimer>
#include <QFile>
#include <QTemporaryDir>
#include <QTimer>

#include <cstdlib>
#include <memory>

#include <fcntl.h>
#include <unistd.h>

using namespace wallpaperx;
using namespace wallpaperx::apptest;
using wallpaperx::testing::check;
using wallpaperx::testing::harnessFailure;
using wallpaperx::testing::notVerified;
using State = KScreenClient::State;

namespace {

constexpr const char* kLogDirVariable = "WALLPAPERX_STANDIN_LOG_DIR";
constexpr const char* kPrefix = "io.wallpaperx.test.Launcher.";
// Each read may include starting a process, so waits are generous; none is graded by its length.
constexpr int kWaitMs = 10000;

void appendLine(const QString& file, const QByteArray& line) {
    const int fd = ::open(QFile::encodeName(file).constData(), O_WRONLY | O_APPEND | O_CREAT | O_CLOEXEC, 0600);
    if (fd >= 0) {
        const QByteArray text = line + '\n';
        [[maybe_unused]] const ssize_t written = ::write(fd, text.constData(), static_cast<size_t>(text.size()));
        ::close(fd);
    }
}

// --- the stand-in, run by the bus -------------------------------------------------------------

class StandIn : public QDBusVirtualObject {
public:
    StandIn(bool crashy, QDBusConnection bus, QString log) : m_crashy(crashy), m_bus(std::move(bus)), m_log(std::move(log)) {}

    QString introspect(const QString&) const override { return {}; }

    bool handleMessage(const QDBusMessage& message, const QDBusConnection&) override {
        if (message.type() != QDBusMessage::MethodCallMessage) {
            return false;
        }
        appendLine(m_log, "call " + message.member().toLatin1());
        if (m_crashy) {
            std::_Exit(3);
        }
        const QString where = message.path() + QLatin1Char(' ') + message.interface() + QLatin1Char('.') + message.member();
        if (where == QLatin1String("/ org.kde.KScreen.requestBackend")) {
            m_bus.send(message.createReply(true));
        } else if (where == QLatin1String("/backend org.kde.kscreen.Backend.getConfig")) {
            m_bus.send(message.createReply(QVariant(configOf({output({.name = QStringLiteral("DP-3"), .id = 2}),
                                                              output({.name = QStringLiteral("DP-4"), .id = 1, .x = qlonglong(1920)})}))));
        } else if (where == QLatin1String("/backend org.kde.kscreen.Backend.getEdid")) {
            m_bus.send(message.createReply(QByteArray()));
        } else if (where == QLatin1String("/ io.wallpaperx.test.Control.Quit")) {
            m_bus.send(message.createReply());
            QTimer::singleShot(0, qApp, &QCoreApplication::quit);
        } else {
            m_bus.send(message.createErrorReply(QDBusError::UnknownMethod, where));
        }
        return true;
    }

private:
    bool m_crashy;
    QDBusConnection m_bus;
    QString m_log;
};

// argv: --stand-in healthy|crashy NAME
int standIn(int argc, char* argv[]) {
    QCoreApplication app(argc, argv);
    const QByteArray starter = qgetenv("DBUS_STARTER_ADDRESS");
    const QByteArray logDir = qgetenv(kLogDirVariable);
    // Only the bus that started it, never DBUS_SESSION_BUS_ADDRESS, which may be the desktop's.
    if (argc != 4 || starter.isEmpty() || logDir.isEmpty()) {
        return 2;
    }
    const QString name = QString::fromLatin1(argv[3]);
    QDBusConnection bus = QDBusConnection::connectToBus(QString::fromLatin1(starter), QStringLiteral("stand-in"));
    if (!bus.isConnected() || !name.startsWith(QLatin1String(kPrefix))) {
        return 3;
    }
    const QString log = QString::fromLocal8Bit(logDir) + QLatin1Char('/') + name + QStringLiteral(".log");
    StandIn object(qstrcmp(argv[2], "crashy") == 0, bus, log);
    if (!bus.registerVirtualObject(QStringLiteral("/"), &object, QDBusConnection::SubPath) || !bus.registerService(name)) {
        return 4;
    }
    appendLine(log, "start");
    // Gone with its bus, and after 30 s regardless, so no stand-in outlives the run.
    QTimer watchdog;
    QObject::connect(&watchdog, &QTimer::timeout, &app, [&bus] {
        if (!bus.isConnected()) {
            QCoreApplication::quit();
        }
    });
    watchdog.start(200);
    QTimer::singleShot(30000, &app, &QCoreApplication::quit);
    const int status = app.exec();
    bus.unregisterObject(QStringLiteral("/"), QDBusConnection::UnregisterTree);
    return status;
}

// --- the test ---------------------------------------------------------------------------------

QElapsedTimer g_clock;
QString g_logDir;

void expect(bool cond, const QString& msg) {
    check(cond, msg.toStdString().c_str());
}

struct Counts {
    int starts = 0;
    int backend = 0;
    int config = 0;
    QString text() const {
        return QStringLiteral("%1 start(s), %2 requestBackend, %3 getConfig").arg(starts).arg(backend).arg(config);
    }
};

Counts countsFor(const QString& name) {
    Counts c;
    QFile file(g_logDir + QLatin1Char('/') + name + QStringLiteral(".log"));
    if (!file.open(QIODevice::ReadOnly)) {
        return c;
    }
    for (const QByteArray& line : file.readAll().split('\n')) {
        c.starts += line == "start";
        c.backend += line == "call requestBackend";
        c.config += line == "call getConfig";
    }
    return c;
}

// GetNameOwner never starts a service.
QString ownerOf(const QString& name) {
    return QDBusConnection::sessionBus().interface()->serviceOwner(name).value();
}

// Asks the stand-in owning `name` to exit, addressed by its unique name so the call cannot start
// another, and waits until it has left. Its leaving is what counts, not a reply: a crashing
// stand-in leaves without one. A failure is the harness's, reported as such.
bool quitOwner(const QString& name, const QString& phase) {
    const QString owner = ownerOf(name);
    if (owner.isEmpty()) {
        harnessFailure((phase + QStringLiteral(": no stand-in owns %1 to be stopped").arg(name)).toStdString());
        return false;
    }
    const QDBusMessage reply = QDBusConnection::sessionBus().call(
        QDBusMessage::createMethodCall(owner, QStringLiteral("/"), QStringLiteral("io.wallpaperx.test.Control"), QStringLiteral("Quit")),
        QDBus::Block, 5000);
    const bool gone = waitFor([&] { return ownerOf(name) != owner; }, kWaitMs);
    if (!gone) {
        harnessFailure((phase + QStringLiteral(": the stand-in %1 did not leave when told to (%2)").arg(owner, reply.errorMessage())).toStdString());
    }
    return gone;
}

qsizetype inFlight(const KScreenClient& c) {
    return c.findChildren<QDBusPendingCallWatcher*>().size();
}

QString stateName(State s) {
    switch (s) {
    case State::Loading: return QStringLiteral("Loading");
    case State::Ready: return QStringLiteral("Ready");
    case State::Unavailable: return QStringLiteral("Unavailable");
    }
    return QStringLiteral("?");
}

bool keepsStopping(const KScreenClient& c) {
    return c.state() == State::Unavailable && c.unavailableReason().contains(QLatin1String("keeps stopping"));
}

// One client against one stand-in name, with every stateChanged snapshotted: a Loading step lasts
// milliseconds, so only a snapshot taken as it is emitted sees it.
struct Phase {
    struct Snap {
        qint64 at;
        State state;
        qsizetype monitors;
        QString selected;
        QString reason;
    };

    QString name;
    std::unique_ptr<KScreenClient> client;
    QList<Snap> snaps;

    Phase(const char* suffix, int stayUpMs)
        : name(QLatin1String(kPrefix) + QLatin1String(suffix))
        , client(std::make_unique<KScreenClient>(QDBusConnection::sessionBus(), name,
                                                 KScreenTimeouts{.backendMs = kWaitMs, .callMs = 3000, .launcherStayUpMs = stayUpMs})) {
        QObject::connect(client.get(), &KScreenClient::stateChanged, [this] {
            snaps.append({g_clock.elapsed(), client->state(), client->monitors().size(), client->selectedOutput(), client->unavailableReason()});
        });
    }
    Phase(const Phase&) = delete;
    Phase& operator=(const Phase&) = delete;
    // The client first, so its retry cannot restart the stand-in being stopped.
    ~Phase() {
        client.reset();
        if (!ownerOf(name).isEmpty()) {
            quitOwner(name, name + QStringLiteral(" cleanup"));
        }
    }

    Counts counts() const { return countsFor(name); }
    bool settled() const { return client->state() != State::Loading && inFlight(*client) == 0; }
    QString summary() const {
        return QStringLiteral("state %1, reason \"%2\", %3 monitor(s), selected \"%4\"; %5")
            .arg(stateName(client->state()), client->unavailableReason())
            .arg(client->monitors().size())
            .arg(client->selectedOutput(), counts().text());
    }
    // A Ready answer handled and nothing left in flight; reported when it does not come.
    bool readyWith(int starts, const QString& phase) {
        const bool ready = waitFor([&] { return settled() && client->state() == State::Ready && counts().starts == starts; }, kWaitMs);
        expect(ready, QStringLiteral("%1: expected Ready from start %2 within %3 ms; %4").arg(phase).arg(starts).arg(kWaitMs).arg(summary()));
        return ready;
    }
    // Keeps the event loop running for `ms`, so anything the client would do in that time is done.
    static void hold(int ms) {
        const qint64 until = g_clock.elapsed() + ms;
        waitFor([&] { return g_clock.elapsed() >= until; }, ms + 1000);
        QCoreApplication::processEvents();
    }
};

// The precondition every phase rests on: the bus starts a stand-in, which logs its start.
bool standInsWork() {
    const QString name = QLatin1String(kPrefix) + QStringLiteral("Probe");
    const QDBusReply<void> started = QDBusConnection::sessionBus().interface()->startService(name);
    const bool logged = started.isValid() && waitFor([&] { return countsFor(name).starts == 1 && !ownerOf(name).isEmpty(); }, kWaitMs);
    if (!logged) {
        harnessFailure(("the bus did not start a stand-in that logged its start (" + started.error().message() + ", " +
                        countsFor(name).text() + ")")
                           .toStdString());
        return false;
    }
    return quitOwner(name, QStringLiteral("probe"));
}

// S15.30
void coldStart() {
    // GOAL: S15.30 -- a first read that starts the launcher through activation reads it once:
    //       one start, one requestBackend, one getConfig, although the launcher's arrival on the
    //       bus is an owner change the client is watching.
    // WHY-THIS-SHAPE: the arrival signal precedes the requestBackend reply on the client's
    //       connection, so once the answer is handled and nothing is in flight, a second read the
    //       arrival caused would already be counted.
    // CONTROL: app/kde/kscreen_client.cpp, onLauncherOwnerChanged's new-owner `&& m_state ==
    //       State::Unavailable` removed -> red, "1 start(s), 2 requestBackend, 1 getConfig";
    //       restored, green.
    Phase p("ColdStart", 60000);
    p.client->refresh();
    if (p.readyWith(1, QStringLiteral("S15.30"))) {
        const Counts c = p.counts();
        expect(c.starts == 1 && c.backend == 1 && c.config == 1,
               QStringLiteral("S15.30: a cold start through activation should read once; ") + p.summary());
    }
}

// S15.27
void crashingLauncher() {
    // GOAL: S15.27 -- a launcher that crashes on its first call is started exactly twice by one
    //       refresh (the first read and the one retry), then the client reads Unavailable "keeps
    //       stopping" and starts it no more; each "Try again" starts it exactly once more.
    // WHY-THIS-SHAPE: starts are the stand-in's own log, not calls, so a restart loop is counted
    //       as processes. Each count is taken after a hold of several stay-up periods with the
    //       event loop running, so a late extra start is inside the count.
    // CONTROL: app/kde/kscreen_client.cpp, onLauncherOwnerChanged's `m_launcherRetrySpent =
    //       true;` deleted -> red, "never settled on "keeps stopping"", ~1000 starts in 10 s; its
    //       loss branch never retrying (`if (true || m_launcherRetrySpent)`) -> red, "1 start(s)";
    //       refresh() clearing `m_launcherRetrySpent`, with the loss branch setting it after its
    //       own refresh() so only other callers clear it -> red, "Try again started it 2 more
    //       time(s)"; restored, green.
    constexpr int stayUpMs = 300;
    Phase p("Crashy", stayUpMs);
    p.client->refresh();
    if (!waitFor([&] { return p.settled() && keepsStopping(*p.client); }, kWaitMs)) {
        expect(false, QStringLiteral("S15.27 crashing launcher: never settled on \"keeps stopping\"; ") + p.summary());
        return;
    }
    Phase::hold(stayUpMs * 3);
    expect(p.counts().starts == 2 && keepsStopping(*p.client),
           QStringLiteral("S15.27 crashing launcher: expected 2 starts and \"keeps stopping\" after three stay-up periods; ") + p.summary());

    const int before = p.counts().starts;
    p.client->refresh();
    if (!waitFor([&] { return p.settled() && keepsStopping(*p.client); }, kWaitMs)) {
        expect(false, QStringLiteral("S15.27 crashing launcher: after Try again, never settled on \"keeps stopping\"; ") + p.summary());
        return;
    }
    Phase::hold(stayUpMs * 3);
    expect(p.counts().starts == before + 1 && keepsStopping(*p.client),
           QStringLiteral("S15.27 crashing launcher: Try again started it %1 more time(s), expected 1; ").arg(p.counts().starts - before) +
               p.summary());
}

// S15.27
void launcherExitsOnce() {
    // GOAL: S15.27 -- a launcher that leaves the bus once after answering is started again and
    //       read: Ready, then Loading with no monitor and no selection, then Ready with the same
    //       choice, never Unavailable; two starts, two requestBackend, two getConfig.
    // WHY-THIS-SHAPE: DP-3 is chosen with two screens selectable, so only the remembered choice
    //       can put it back. The Loading step is read from the snapshots taken at each
    //       stateChanged, since polling cannot see a step that lasts milliseconds.
    // CONTROL: app/kde/kscreen_client.cpp, the loss's `settle(State::Loading, {}, {})` given
    //       `m_monitors` -> red, "the client went Loading/2/"DP-3" -> Ready/2/"DP-3""; settle()'s
    //       `if (m_state == State::Ready)` made `m_state != State::Unavailable`, so a Loading step
    //       reconciles the choice -> red, "expected Ready with DP-3 selected again", selected "";
    //       restored, green.
    Phase p("ExitOnce", 60000);
    p.client->refresh();
    if (!p.readyWith(1, QStringLiteral("S15.27 exits once")) || !p.client->select(QStringLiteral("DP-3"))) {
        expect(false, QStringLiteral("S15.27 exits once: could not reach Ready with DP-3 selected; ") + p.summary());
        return;
    }
    const qsizetype mark = p.snaps.size();
    if (!quitOwner(p.name, QStringLiteral("S15.27 exits once")) || !p.readyWith(2, QStringLiteral("S15.27 exits once"))) {
        return;
    }
    const QList<Phase::Snap> after = p.snaps.mid(mark);
    QStringList seen;
    bool loadingEmpty = false;
    bool unavailable = false;
    for (const Phase::Snap& s : after) {
        seen.append(QStringLiteral("%1/%2/\"%3\"").arg(stateName(s.state)).arg(s.monitors).arg(s.selected));
        loadingEmpty |= s.state == State::Loading && s.monitors == 0 && s.selected.isEmpty();
        unavailable |= s.state == State::Unavailable;
    }
    expect(!after.isEmpty() && after.front().state == State::Loading && loadingEmpty && !unavailable,
           QStringLiteral("S15.27 exits once: expected Loading with no monitor, then Ready; the client went %1")
               .arg(seen.join(QStringLiteral(" -> "))));
    const Counts c = p.counts();
    expect(p.client->selectedOutput() == QStringLiteral("DP-3") && p.client->monitors().size() == 2 && c.backend == 2 && c.config == 2,
           QStringLiteral("S15.27 exits once: expected Ready with DP-3 selected again after one more read; ") + p.summary());
}

// S15.27
void launcherExitsAfterEveryAnswer() {
    // GOAL: S15.27 -- a launcher that leaves shortly after every answer, sooner than the stay-up
    //       period, is started exactly twice: the second loss, before the period has run from the
    //       retry's Ready answer, reads Unavailable "keeps stopping", and nothing starts it again.
    // WHY-THIS-SHAPE: the second loss must land inside the period, so the verdict is taken only
    //       when the client's reaction came less than 9/10 of a period after it went Loading for
    //       the retry (the period cannot have started earlier); otherwise not verified.
    // CONTROL: app/kde/kscreen_client.cpp, settle()'s `m_launcherStayUp.start();` made
    //       `m_launcherRetrySpent = false;`, so any Ready answer re-arms the retry -> red,
    //       "expected 2 starts and "keeps stopping"" with 3 starts; restored, green.
    constexpr int stayUpMs = 600;
    Phase p("ExitEvery", stayUpMs);
    p.client->refresh();
    if (!p.readyWith(1, QStringLiteral("S15.27 exits after every answer"))) {
        return;
    }
    const qsizetype first = p.snaps.size();
    if (!quitOwner(p.name, QStringLiteral("S15.27 exits after every answer")) || !p.readyWith(2, QStringLiteral("S15.27 exits after every answer"))) {
        return;
    }
    const qint64 retryAt = p.snaps.value(first).at;
    const qsizetype second = p.snaps.size();
    if (!quitOwner(p.name, QStringLiteral("S15.27 exits after every answer"))) {
        return;
    }
    if (!waitFor([&] { return p.settled() && (p.client->state() == State::Unavailable || p.counts().starts >= 3); }, kWaitMs) ||
        p.snaps.size() == second) {
        expect(false, QStringLiteral("S15.27 exits after every answer: the second loss led nowhere; ") + p.summary());
        return;
    }
    const qint64 reactedAfter = p.snaps[second].at - retryAt;
    if (reactedAfter >= stayUpMs * 9 / 10) {
        notVerified("S15.27 (exits after every answer)",
                    "the second loss was handled " + std::to_string(reactedAfter) + " ms after the retry, too close to the " +
                        std::to_string(stayUpMs) + " ms stay-up period to say which came first");
        return;
    }
    expect(p.counts().starts == 2 && keepsStopping(*p.client),
           QStringLiteral("S15.27 exits after every answer: expected 2 starts and \"keeps stopping\" (second loss %1 ms after the retry); ")
                   .arg(reactedAfter) +
               p.summary());
    Phase::hold(stayUpMs * 3);
    expect(p.counts().starts == 2 && keepsStopping(*p.client),
           QStringLiteral("S15.27 exits after every answer: started again within three stay-up periods; ") + p.summary());
}

// S15.29
void launcherStaysUpBetweenStops() {
    // GOAL: S15.29 -- a launcher that stays up longer than the stay-up period after each Ready
    //       answer is recovered from every stop: three stops, four starts, four requestBackend and
    //       four getConfig, Ready with the same choice each time.
    // WHY-THIS-SHAPE: each stop is sent after an event-loop pass made 1.4 periods after the Ready
    //       answer was seen; the period's timer started before that answer and Qt lets a coarse
    //       timer run at most 5% late, so that pass has dispatched it however late this thread ran.
    // CONTROL: app/kde/kscreen_client.cpp, settle()'s `m_launcherStayUp.start();` deleted, so the
    //       retry is never re-armed -> red, "stop 2 ... did not end Ready", Unavailable "keeps
    //       stopping" with 2 starts; restored, green.
    constexpr int stayUpMs = 400;
    Phase p("StaysUp", stayUpMs);
    p.client->refresh();
    if (!p.readyWith(1, QStringLiteral("S15.29 stays up")) || !p.client->select(QStringLiteral("DP-3"))) {
        expect(false, QStringLiteral("S15.29 stays up: could not reach Ready with DP-3 selected; ") + p.summary());
        return;
    }
    for (int stop = 1; stop <= 3; ++stop) {
        Phase::hold(stayUpMs * 14 / 10);
        if (!quitOwner(p.name, QStringLiteral("S15.29 stays up"))) {
            return;
        }
        const bool recovered = waitFor([&] { return p.settled() && (p.client->state() == State::Unavailable || p.counts().starts == stop + 1); }, kWaitMs) &&
                               p.client->state() == State::Ready && p.client->selectedOutput() == QStringLiteral("DP-3");
        if (!recovered) {
            expect(false, QStringLiteral("S15.29 stays up: stop %1, after 1.4 stay-up periods up, did not end Ready with DP-3 selected; ")
                                  .arg(stop) +
                              p.summary());
            return;
        }
    }
    const Counts c = p.counts();
    expect(c.starts == 4 && c.backend == 4 && c.config == 4,
           QStringLiteral("S15.29 stays up: expected 4 starts, 4 requestBackend, 4 getConfig; ") + p.summary());
}

// S15.29
void laterReadyKeepsThePeriod() {
    // GOAL: S15.29 -- the stay-up period runs from the first Ready answer after a retry: a later
    //       Ready answer from the same launcher ("Try again" here) does not restart it, so a loss
    //       after the period, counted from the first answer, is retried.
    // WHY-THIS-SHAPE: "Try again" at 0.9 of the period, the loss at 1.4: the verdict is taken
    //       only when the client reacted before 0.9 of a period had run from the "Try again", so a
    //       period restarted by that answer cannot have ended; otherwise not verified.
    // CONTROL: app/kde/kscreen_client.cpp, settle()'s `&& !m_launcherStayUp.isActive()` removed,
    //       so every Ready answer restarts the period -> red, "a loss 1.4 periods after the first
    //       Ready was not retried"; restored, green.
    constexpr int stayUpMs = 1000;
    Phase p("LaterReady", stayUpMs);
    p.client->refresh();
    if (!p.readyWith(1, QStringLiteral("S15.29 later Ready")) || !quitOwner(p.name, QStringLiteral("S15.29 later Ready")) ||
        !p.readyWith(2, QStringLiteral("S15.29 later Ready"))) {
        return;
    }
    const qint64 firstReady = g_clock.elapsed();
    Phase::hold(stayUpMs * 9 / 10);
    const qint64 tryAgainAt = g_clock.elapsed();
    const int backendBefore = p.counts().backend;
    p.client->refresh();
    if (!waitFor([&] { return p.settled() && p.counts().backend == backendBefore + 1; }, kWaitMs) || p.client->state() != State::Ready) {
        expect(false, QStringLiteral("S15.29 later Ready: Try again was not answered Ready; ") + p.summary());
        return;
    }
    Phase::hold(static_cast<int>(firstReady + stayUpMs * 14 / 10 - g_clock.elapsed()));
    const qsizetype mark = p.snaps.size();
    if (!quitOwner(p.name, QStringLiteral("S15.29 later Ready"))) {
        return;
    }
    if (!waitFor([&] { return p.settled() && (p.client->state() == State::Unavailable || p.counts().starts == 3); }, kWaitMs) ||
        p.snaps.size() == mark) {
        expect(false, QStringLiteral("S15.29 later Ready: the loss led nowhere; ") + p.summary());
        return;
    }
    const qint64 reactedAfterTryAgain = p.snaps[mark].at - tryAgainAt;
    if (reactedAfterTryAgain >= stayUpMs * 9 / 10) {
        notVerified("S15.29 (a later Ready answer)", "the loss was handled " + std::to_string(reactedAfterTryAgain) +
                                                         " ms after Try again, too late to tell a restarted period from the first");
        return;
    }
    expect(p.client->state() == State::Ready && p.counts().starts == 3,
           QStringLiteral("S15.29 later Ready: a loss 1.4 periods after the first Ready was not retried; ") + p.summary());
}

// S15.29
void destroyedDuringThePeriod() {
    // GOAL: S15.29 -- a client destroyed while the stay-up period runs does nothing afterwards:
    //       the period's end touches no freed memory and no call reaches the launcher.
    // WHY-THIS-SHAPE: this binary is built with AddressSanitizer, so a callback that outlives the
    //       client and writes to it aborts the run with a report instead of passing silently; the
    //       event loop runs for three periods after the destruction.
    // CONTROL: app/kde/kscreen_client.cpp, settle()'s `m_launcherStayUp.start();` made
    //       `QTimer::singleShot(m_timeouts.launcherStayUpMs, [this] { m_launcherRetrySpent = false; });`
    //       (no context object) -> red, AddressSanitizer "heap-use-after-free"; restored, green.
    constexpr int stayUpMs = 300;
    Phase p("Destroyed", stayUpMs);
    p.client->refresh();
    if (!p.readyWith(1, QStringLiteral("S15.29 destroyed")) || !quitOwner(p.name, QStringLiteral("S15.29 destroyed")) ||
        !p.readyWith(2, QStringLiteral("S15.29 destroyed"))) {
        return;
    }
    const Counts before = p.counts();
    p.client.reset();
    Phase::hold(stayUpMs * 3);
    const Counts after = p.counts();
    expect(after.starts == before.starts && after.backend == before.backend && after.config == before.config,
           QStringLiteral("S15.29 destroyed: the launcher saw %1 after the client was destroyed, %2 before").arg(after.text(), before.text()));
}

} // namespace

int main(int argc, char* argv[]) {
    if (argc > 1 && qstrcmp(argv[1], "--stand-in") == 0) {
        return standIn(argc, argv);
    }
    wallpaperx::testing::g_testName = "kscreen_launcher";
    if (const auto refused = refuseUnlessUnderDbusRunSession()) {
        return *refused;
    }
    QCoreApplication app(argc, argv);
    const QStringList names = QStringLiteral(WALLPAPERX_STANDIN_NAMES).split(u';', Qt::SkipEmptyParts);
    if (const auto refused = refuseUnlessPrivateBus(names)) {
        return *refused;
    }

    // GOAL (harness): a stand-in the bus cannot start, or that cannot log, fails the run as the
    //       harness's fault before any phase could blame the client for it.
    // CONTROL: by hand, test-side: the variable set below renamed, so stand-ins find no log
    //       directory -> "FAIL (harness): the bus did not start a stand-in that logged its start
    //       (Process io.wallpaperx.test.Launcher.Probe exited with status 2...)", exit 1; restored.
    const QTemporaryDir logDir;
    qDBusRegisterMetaType<QMap<QString, QString>>();
    QDBusMessage setEnv = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.DBus"), QStringLiteral("/org/freedesktop/DBus"),
                                                         QStringLiteral("org.freedesktop.DBus"), QStringLiteral("UpdateActivationEnvironment"));
    setEnv << QVariant::fromValue(QMap<QString, QString>{{QString::fromLatin1(kLogDirVariable), logDir.path()}});
    const QDBusMessage envReply = QDBusConnection::sessionBus().call(setEnv);
    g_logDir = logDir.path();
    if (!logDir.isValid() || envReply.type() != QDBusMessage::ReplyMessage) {
        harnessFailure("the stand-ins' log directory could not be set up: " + envReply.errorMessage().toStdString());
    } else if (standInsWork()) {
        g_clock.start();
        coldStart();
        crashingLauncher();
        launcherExitsOnce();
        launcherExitsAfterEveryAnswer();
        launcherStaysUpBetweenStops();
        laterReadyKeepsThePeriod();
        destroyedDuringThePeriod();
    }

    const bool failed = wallpaperx::testing::reportCheckFailures();
    const bool faulted = wallpaperx::testing::reportHarnessFaults("in this test file or its stand-in launchers, not in the app");
    if (failed || faulted) {
        return 1;
    }
    return wallpaperx::testing::reportNotVerifiedOrPassed();
}
